  t["&nbsp;·&nbsp; radio de curvatura $R = "] = "&nbsp;·&nbsp; radius of curvature $R = ";
  t["(-1/x^2)}{1/x + 1/x^2}$, que en $x = 1$ vale $\\frac{"] = "(-1/x^2)}{1/x + 1/x^2}$, which at $x = 1$ equals $\\frac{";
  t["(1/x - 1)}{\\ln x + (x - 1)/x}$, otra vez $\\frac{0}{0}$."] = "(1/x - 1)}{\\ln x + (x - 1)/x}$, again $\\frac{0}{0}$.";
  t["(3,4,5) \\quad (5,12,13) \\quad (8,15,17) \\quad (7,24,25) \\quad (20,21,29)"] = "(3,\\,4,\\,5) \\quad (5,\\,12,\\,13) \\quad (8,\\,15,\\,17) \\quad (7,\\,24,\\,25) \\quad (20,\\,21,\\,29)";
  t["(\\ln x - x + 1)}{(x - 1)\\ln x}$, que es $\\frac{0}{0}$."] = "(\\ln x - x + 1)}{(x - 1)\\ln x}$, which is $\\frac{0}{0}$.";
