  t["<strong>glslsandbox.com</strong>, más viejo y más crudo, permite bifurcar el de cualquiera con un clic."] = "<strong>glslsandbox.com</strong>, older and rawer, lets you fork anybody's with one click.";
  t["<strong>hacia arriba</strong>: $n = "] = "<strong>upwards</strong>: $n = ";
  t["<strong>hierba</strong> donde $n_y \\ge 0{,}8$ y <strong>roca</strong> en el resto, con un corte limpio"] = "<strong>grass</strong> where $n_y \\ge 0{.}8$ and <strong>rock</strong> elsewhere, with a clean cut";
  t["<strong>incompatible</strong>"] = "<strong>inconsistent</strong>";
  t["<strong>longitud</strong> (perímetro) en cm"] = "<strong>circumference</strong> in cm";
  t["<strong>líneas de barrido</strong>: rebajar un 30 % siguiendo <code>1 - 0.3·(1-cos(fragCoord.y·PI))/2</code>"] = "<strong>scanlines</strong>: cutting 30 % following <code>1 - 0.3·(1-cos(fragCoord.y·PI))/2</code>";
  t["<strong>m.c.d.</strong> (máximo común divisor): factores <em>comunes</em> con el <em>menor</em> exponente."] = "<strong>gcd</strong> (greatest common divisor): <em>common</em> factors with the <em>smallest</em> exponent.";
  t["<strong>m.c.m.</strong> (mínimo común múltiplo): factores <em>comunes y no comunes</em> con el <em>mayor</em> exponente."] = "<strong>lcm</strong> (least common multiple): <em>common and non-common</em> factors with the <em>largest</em> exponent.";
  t["<strong>menor</strong> "] = "<strong>smallest</strong> ";
  t["<strong>menos</strong>"] = "<strong>less</strong>";
  t["<strong>muy pequeña</strong>, avanza a paso de tortuga y necesita muchísimas iteraciones."] = "<strong>very small</strong>, it advances at a snail's pace and needs a great many iterations.";
  t["<strong>más contraste</strong>: la distancia de cada canal al gris medio 0,5, multiplicada por 1,5"] = "<strong>more contrast</strong>: each channel's distance from the middle grey 0.5, multiplied by 1.5";
  t["<strong>más</strong>"] = "<strong>more</strong>";
  t["<strong>nieve</strong> por encima de la altura 1,5 y <strong>roca</strong> por debajo, con un corte limpio"] = "<strong>snow</strong> above height 1.5 and <strong>rock</strong> below, with a clean cut";
  t["<strong>nieve</strong> solo donde a la vez es alto, por encima de 1,5, y llano, con $n_y \\ge 0{,}8$; <strong>roca</strong> en el resto"] = "<strong>snow</strong> only where it is both high, above 1.5, and flat, with $n_y \\ge 0{.}8$; <strong>rock</strong> elsewhere";
  t["<strong>no es primo</strong>: $"] = "<strong>it is not prime</strong>: $";
  t["<strong>no</strong> están en $A$"] = "are <strong>not</strong> in $A$";
  t["<strong>no</strong> ocurre $A$"] = "$A$ does <strong>not</strong> happen";
  t["<strong>paralela</strong>"] = "<strong>parallel</strong>";
  t["<strong>recíproca</strong>"] = "<strong>converse</strong>";
  t["<strong>rotaciones</strong>"] = "<strong>rotations</strong>";
