  t["Comprobación con la tabla: $\\operatorname{sen} "] = "Check against the table: $\\sin ";
  t["Comprobación con los marginales: $I'(x) = "] = "Check with the marginals: $I'(x) = ";
  t["Comprobación de grados: $2 + 1 = 3$ ✓"] = "Check on the degrees: $2 + 1 = 3$ ✓";
  t["Comprobación de las restricciones: $"] = "Check on the constraints: $";
  t["Comprobación de perpendicularidad: $\\vec{u}\\cdot(\\vec{u}\\times\\vec{v}) = "] = "Perpendicularity check: $\\vec{u}\\cdot(\\vec{u}\\times\\vec{v}) = ";
  t["Comprobación directa: $"] = "Direct check: $";
  t["Comprobación directa: $\\operatorname{sen} "] = "Direct check: $\\sin ";
