  t["Cuadrado: $(x^2 - y^2,\\ 2xy)$. Luego suma $c$."] = "Square: $(x^2 - y^2,\\ 2xy)$. Then add $c$.";
  t["Cuadrados de grises"] = "Squares of greys";
