  t["P(\\text{alguna coincidencia entre } k) \\approx 1 - e^{-k^2 / (2N)}, \\qquad k \\approx 1{,}18\\sqrt{N} \\text{ para } P = \\tfrac12"] = "P(\\text{some match among } k) \\approx 1 - e^{-k^2 / (2N)}, \\qquad k \\approx 1{.}18\\sqrt{N} \\text{ for } P = \\tfrac12";
  t["P(\\text{base coincide}) = \\tfrac12 \\Rightarrow \\text{clave cribada} \\approx \\tfrac{n}{2} \\text{ bits}"] = "P(\\text{bases agree}) = \\tfrac12 \\Rightarrow \\text{sifted key} \\approx \\tfrac{n}{2} \\text{ bits}";
  t["P(\\text{engañar en } n \\text{ rondas}) = 2^{-n}"] = "P(\\text{cheating in } n \\text{ rounds}) = 2^{-n}";
  t["P(\\text{error en un bit cribado} \\mid \\text{Eva mide y reenvía}) = \\tfrac14"] = "P(\\text{error in a sifted bit} \\mid \\text{Eve measures and resends}) = \\tfrac14";
  t["P(\\text{jugada } i) = \\frac{n_i}{n_1 + n_2 + \\dots + n_k}"] = "P(\\text{move } i) = \\frac{n_i}{n_1 + n_2 + \\dots + n_k}";
  t["P(\\text{mejor opción}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{n}, \\qquad P(\\text{otra concreta}) = \\frac{\\varepsilon}{n}"] = "P(\\text{best option}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{n}, \\qquad P(\\text{a specific other}) = \\frac{\\varepsilon}{n}";
