  t["Presas"] = "Prey";
  t["Presentar $s_1 s_2 \\bmod n$ como firma válida del importe 30 000"] = "Present $s_1 s_2 \\bmod n$ as a valid signature for the amount 30,000";
  t["Presión"] = "Pressure";
