  t["Quédate con la mitad en la que $f$ cambia de signo, y repite."] = "Keep the half on which $f$ changes sign, and repeat.";
  t["R = f(D) \\quad \\text{en todo regulador óptimo}"] = "R = f(D) \\quad \\text{in every optimal regulator}";
  t["R(\\alpha) = \\begin{pmatrix} \\cos\\alpha & -\\operatorname{sen}\\alpha \\\\ \\operatorname{sen}\\alpha & \\cos\\alpha \\end{pmatrix}"] = "R(\\alpha) = \\begin{pmatrix} \\cos\\alpha & -\\sin\\alpha \\\\ \\sin\\alpha & \\cos\\alpha \\end{pmatrix}";
