  t["Reutilizar la clave lo arruina: $c_1 \\oplus c_2 = m_1 \\oplus m_2$."] = "Reusing the key ruins it: $c_1 \\oplus c_2 = m_1 \\oplus m_2$.";
  t["Reutilizar la clave «solo una vez más»"] = "Reusing the key “just once more”";
