  t["Sustituye $x = "] = "Substitute $x = ";
  t["Sustituye $x = -1$ en la ecuación de partida, no en una intermedia. ¿Sale 1?"] = "Substitute $x = -1$ into the equation you started from, not into an intermediate one. Does it give 1?";
  t["Sustituye $x = 0$. ¿Qué vale el denominador?"] = "Substitute $x = 0$. What is the denominator?";
